import threading
import time
import copy
from dataclasses import dataclass, field
from typing import Dict, Set, Optional, Callable, FrozenSet, Tuple
from functools import wraps


@dataclass(frozen=True)
class PermissionSnapshot:
    """Immutable snapshot of user permissions at a point in time."""
    user_id: str
    roles: FrozenSet[str]
    permissions: Tuple[Tuple[str, bool], ...]
    active: bool
    snapshot_time: float


@dataclass
class UserProfile:
    user_id: str
    roles: Set[str] = field(default_factory=set)
    permissions: Dict[str, bool] = field(default_factory=dict)
    active: bool = True
    _version: int = 0


class PermissionStore:
    """Thread-safe permission store with role-based access control."""

    def __init__(self):
        self._lock = threading.RLock()
        self._profiles: Dict[str, UserProfile] = {}

    def create_user(self, user_id: str, roles: Set[str] = None) -> UserProfile:
        with self._lock:
            profile = UserProfile(
                user_id=user_id,
                roles=roles or set(),
                permissions=self._compute_permissions(roles or set()),
                active=True
            )
            self._profiles[user_id] = profile
            return profile

    def get_snapshot(self, user_id: str) -> Optional[PermissionSnapshot]:
        """Get an immutable snapshot of the user's current permissions."""
        with self._lock:
            profile = self._profiles.get(user_id)
            if profile is None:
                return None
            return PermissionSnapshot(
                user_id=profile.user_id,
                roles=frozenset(profile.roles),
                permissions=tuple(sorted(profile.permissions.items())),
                active=profile.active,
                snapshot_time=time.time()
            )

    def update_roles(self, user_id: str, new_roles: Set[str]) -> bool:
        with self._lock:
            profile = self._profiles.get(user_id)
            if profile is None:
                return False
            profile.roles = new_roles
            profile.permissions = self._compute_permissions(new_roles)
            profile._version += 1
            return True

    def deactivate_user(self, user_id: str) -> bool:
        with self._lock:
            profile = self._profiles.get(user_id)
            if profile is None:
                return False
            profile.active = False
            profile.roles = set()
            profile.permissions = {}
            profile._version += 1
            return True

    def _compute_permissions(self, roles: Set[str]) -> Dict[str, bool]:
        """Compute effective permissions from roles."""
        perms = {}
        role_perms = {
            'admin': {'read': True, 'write': True, 'delete': True, 'admin': True},
            'editor': {'read': True, 'write': True, 'delete': False, 'admin': False},
            'viewer': {'read': True, 'write': False, 'delete': False, 'admin': False},
        }
        for role in roles:
            for perm, granted in role_perms.get(role, {}).items():
                if granted:
                    perms[perm] = True
                elif perm not in perms:
                    perms[perm] = False
        return perms


class AuthorizationMiddleware:
    """Middleware that creates authorization contexts for request processing."""

    def __init__(self, store: PermissionStore):
        self._store = store

    def create_auth_context(self, user_id: str) -> Optional[Callable[[str], bool]]:
        """Create an authorization checker bound to an immutable snapshot.

        Returns a callable that checks if the user has a specific permission.
        The checker uses a frozen snapshot taken at context creation time,
        ensuring consistent authorization decisions throughout request processing.
        """
        snapshot = self._store.get_snapshot(user_id)
        if snapshot is None:
            return None

        # Convert permissions tuple back to dict for efficient lookup
        # This is a LOCAL copy - mutations to the store won't affect it
        perm_dict = dict(snapshot.permissions)
        is_active = snapshot.active

        def check_permission(required_perm: str) -> bool:
            if not is_active:
                return False
            return perm_dict.get(required_perm, False)

        return check_permission


class ResourceHandler:
    """Handles resource operations with authorization."""

    def __init__(self, middleware: AuthorizationMiddleware):
        self._middleware = middleware
        self._resources: Dict[str, str] = {'doc1': 'sensitive data', 'doc2': 'public info'}
        self._audit_log = []
        self._log_lock = threading.Lock()

    def handle_request(self, user_id: str, action: str, resource_id: str) -> dict:
        """Process a resource request with full authorization."""
        # Step 1: Create authorization context (takes immutable snapshot)
        auth_check = self._middleware.create_auth_context(user_id)
        if auth_check is None:
            return {'status': 'error', 'message': 'user not found'}

        # Step 2: Validate resource exists
        self._validate_resource(resource_id)

        # Step 3: Check permission using the immutable auth context
        if not auth_check(action):
            with self._log_lock:
                self._audit_log.append(f'DENIED: {user_id} -> {action} on {resource_id}')
            return {'status': 'denied', 'message': f'no {action} permission'}

        # Step 4: Perform the action
        result = self._execute_action(action, resource_id)
        with self._log_lock:
            self._audit_log.append(f'ALLOWED: {user_id} -> {action} on {resource_id}')
        return {'status': 'success', 'data': result}

    def _validate_resource(self, resource_id: str):
        if resource_id not in self._resources:
            raise ValueError(f'Resource {resource_id} not found')

    def _execute_action(self, action: str, resource_id: str) -> str:
        if action == 'read':
            return self._resources.get(resource_id, '')
        elif action == 'delete':
            data = self._resources.pop(resource_id, '')
            return f'deleted: {data}'
        elif action == 'write':
            self._resources[resource_id] = 'modified'
            return 'written'
        return 'unknown action'


def demonstrate_safety():
    """Demonstrate that authorization is based on immutable snapshots."""
    store = PermissionStore()
    middleware = AuthorizationMiddleware(store)
    handler = ResourceHandler(middleware)

    # Setup: Create viewer user
    store.create_user('bob', {'viewer'})

    # Create auth context for bob (snapshot taken: viewer permissions)
    bob_auth = middleware.create_auth_context('bob')

    # Verify: bob cannot delete
    print(f'Bob delete before upgrade: {bob_auth("delete")}')

    # Even if bob's roles are upgraded after context creation...
    store.update_roles('bob', {'admin'})

    # The auth context still reflects the ORIGINAL snapshot
    print(f'Bob delete after upgrade: {bob_auth("delete")}')
    # ^^^ This prints False! The auth context is an immutable snapshot.

    # A NEW auth context would reflect the upgrade
    bob_auth_new = middleware.create_auth_context('bob')
    print(f'Bob delete with new context: {bob_auth_new("delete")}')
    # ^^^ This prints True - new snapshot reflects current state.


if __name__ == '__main__':
    demonstrate_safety()
